INSERT INTO public.job_vacancies (id, industry_id, judul_posisi, tipe_pekerjaan, kuota_penerimaan, gaji_estimasi, kualifikasi, persyaratan, lokasi_penempatan)
VALUES
  ('b0000001-0000-0000-0000-000000000001', 'a0000001-0000-0000-0000-000000000001', 'Operator Perakitan Mesin Traktor', 'Penuh Waktu', 10, 'Rp 2.450.000 - Rp 3.200.000', 'Laki-laki/Perempuan, usia maksimal 23 tahun, mampu membaca gambar teknik dan memakai alat ukur jangka sorong.', ARRAY['Fotokopi Ijazah / SKL SMK Mesin/Otomotif', 'CV & Pas Foto 4x6', 'Surat Keterangan Sehat Dokter'], 'Pabrik Yogyakarta & Tuksono Kulon Progo'),
  ('b0000001-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000001', 'Teknisi Pengelasan & Fabrikasi Welder', 'Penuh Waktu', 5, 'Rp 2.600.000 - Rp 3.500.000', 'Menguasai teknik las busur listrik SMAW atau MIG/GMAW, teliti, tidak buta warna, dan disiplin tinggi.', ARRAY['Sertifikat Uji Kompetensi Las', 'Fotokopi KTP & SKCK Aktif', 'Portofolio Pengelasan'], 'Pabrik Yogyakarta'),
  ('b0000001-0000-0000-0000-000000000003', 'a0000001-0000-0000-0000-000000000002', 'Terapis Pria & Wanita (Massage & Reflexology)', 'Penuh Waktu', 70, 'Rp 2.500.000 - Rp 4.500.000 + Komisi', 'Pria/Wanita usia 18-35 tahun, ramah, beretika baik, bersedia mengikuti training gratis bersertifikat.', ARRAY['Fotokopi KTP & Ijazah', 'Daftar Riwayat Hidup / CV', 'Pas Foto 4x6'], 'Cabang Magelang, Yogyakarta & Jateng'),
  ('b0000001-0000-0000-0000-000000000004', 'a0000001-0000-0000-0000-000000000002', 'Kasir & Front Office Receptionist', 'Penuh Waktu', 15, 'Rp 2.300.000 - Rp 3.200.000', 'Wanita, berpenampilan rapi, ramah melayani tamu, menguasai sistem POS kasir dan Microsoft Office.', ARRAY['CV & Foto Full Body', 'Fotokopi Ijazah / SKL', 'Surat Pengalaman Kerja (jika ada)'], 'Outlet Magelang'),
  ('b0000001-0000-0000-0000-000000000005', 'a0000001-0000-0000-0000-000000000002', 'Supervisor Operasional Cabang', 'Penuh Waktu', 15, 'Rp 3.500.000 - Rp 5.000.000', 'Memiliki jiwa kepemimpinan, mampu mengatur shift kerja terapis, dan berorientasi pada kepuasan pelanggan.', ARRAY['CV Lengkap', 'Portofolio / Pengalaman Manajerial', 'Fotokopi KTP & Ijazah'], 'Jawa Tengah & DIY'),
  ('b0000001-0000-0000-0000-000000000006', 'a0000001-0000-0000-0000-000000000003', 'Sales Jewelry Specialist / Frontliner', 'Penuh Waktu', 40, 'Rp 2.400.000 - Rp 3.800.000 + Insentif', 'Pria/Wanita berpenampilan rapi, jujur, komunikatif, mampu menawarkan perhiasan emas dengan ramah.', ARRAY['CV & Foto Diri Rapi', 'Fotokopi KTP & Ijazah', 'SKCK Aktif Kepolisian'], 'Gerai HK Gold Magelang'),
  ('b0000001-0000-0000-0000-000000000007', 'a0000001-0000-0000-0000-000000000003', 'Kasir & Admin Timbangan Emas', 'Penuh Waktu', 20, 'Rp 2.300.000 - Rp 3.200.000', 'Teliti tinggi, terbiasa mencatat arus kas, menghitung berat kadar emas, dan disiplin administrasi.', ARRAY['Surat Lamaran & CV', 'Transkrip Nilai / Rapor', 'Fotokopi KTP'], 'Gerai HK Gold Magelang'),
  ('b0000001-0000-0000-0000-000000000008', 'a0000001-0000-0000-0000-000000000004', 'Program Pelatihan & Penempatan Vokasi Industri', 'Kontrak Pelatihan & Penempatan', 120, 'Uang Saku + Sertifikasi BNSP + Penempatan Kerja', 'Pria/Wanita lulusan SMK/SMA yang bertekad kuat meningkatkan kompetensi teknis siap kerja industri.', ARRAY['Fotokopi Ijazah / SKL', 'Kartu Keluarga & KTP', 'Pas Foto 3x4'], 'Magelang & Mitra Industri Nasional'),
  ('b0000001-0000-0000-0000-000000000009', 'a0000001-0000-0000-0000-000000000004', 'Program Diklat Administrasi Bisnis & Ritel', 'Kontrak Pelatihan & Penempatan', 80, 'Uang Saku + Sertifikasi BNSP + Penempatan Kerja', 'Memiliki minat di bidang administrasi, operasional ritel, dan layanan pelanggan profesional.', ARRAY['Surat Pendaftaran & CV', 'Fotokopi KTP', 'Pas Foto Berwarna'], 'Magelang'),
  ('b0000001-0000-0000-0000-000000000010', 'a0000001-0000-0000-0000-000000000005', 'Cruise Line Shipboard Crew (F&B, Housekeeping, Bar)', 'Kontrak Internasional Kapal Pesiar', 600, '$800 - $2.500 USD / Bulan (Makan & Akomodasi Ditanggung)', 'Pria/Wanita usia 18-35 tahun, bahasa Inggris dasar aktif, sehat jasmani rohani, bebas tato terlihat.', ARRAY['CV Bahasa Inggris', 'Paspor (jika ada)', 'Fotokopi Ijazah Terakhir', 'Pas Foto 4x6'], 'Kapal Pesiar Karibia, Eropa & Asia Pasifik'),
  ('b0000001-0000-0000-0000-000000000011', 'a0000001-0000-0000-0000-000000000005', 'International Hotel Staff (Timur Tengah & Asia Pasifik)', 'Penuh Waktu', 400, 'Rp 8.000.000 - Rp 15.000.000 / Bulan', 'Pekerja keras, antusias berkarir di hotel bintang 4-5 mancanegara, disiplin perhotelan tinggi.', ARRAY['Curriculum Vitae', 'Sertifikat PKL / Pelatihan', 'Fotokopi KTP & KK'], 'Uni Emirat Arab, Qatar, Malaysia, Maladewa'),
  ('b0000001-0000-0000-0000-000000000012', 'a0000001-0000-0000-0000-000000000006', 'Konseling Karir & Registrasi Program Diklat Perhotelan', 'Bimbingan & Program Diklat Profesi', 0, 'Bimbingan Penempatan Kerja Resmi Internasional', 'Pria/Wanita yang berminat mendalami karir di bidang perhotelan nasional dan kapal pesiar mewah.', ARRAY['Fotokopi KTP & Kartu Keluarga', 'Pas Foto 3x4 (3 lembar)', 'Fotokopi Ijazah / SKL'], 'Kampus LPK Platinum Magelang'),
  ('b0000001-0000-0000-0000-000000000013', 'a0000001-0000-0000-0000-000000000007', 'Program Kerja Tokutei Ginou / SSW Jepang', 'Kontrak Kerja 3-5 Tahun di Jepang', 60, '¥160.000 - ¥220.000 JPY / Bulan (Rp 17 - 24 Juta)', 'Usia 18-28 tahun, fisik prima, tidak bertato/tindik (pria), bersedia mengikuti pelatihan bahasa Jepang intensif.', ARRAY['KTP & Kartu Keluarga', 'Surat Izin Orang Tua', 'Ijazah Terakhir', 'Medical Check Up'], 'Tokyo, Osaka, Nagoya & Prefektur Jepang'),
  ('b0000001-0000-0000-0000-000000000014', 'a0000001-0000-0000-0000-000000000007', 'Program Magang Kerja Ginou Jisshuusei (Pabrik & Pertanian)', 'Kontrak Magang 3 Tahun di Jepang', 40, '¥140.000 - ¥180.000 JPY / Bulan + Asuransi Lengkap', 'Pekerja keras, ulet, patuh pada aturan ketat keselamatan kerja di pabrik dan perkebunan modern Jepang.', ARRAY['Fotokopi Dokumen Kependudukan', 'CV Lengkap', 'Pas Foto 3x4 Background Putih'], 'Kawasan Industri Jepang'),
  ('b0000001-0000-0000-0000-000000000015', 'a0000001-0000-0000-0000-000000000008', 'Operator Jahit (Sewing Machine Operator)', 'Penuh Waktu', 140, 'Sesuai UMK Magelang + Premi Jahit & Lembur', 'Pria/Wanita usia 18-35 tahun, mampu mengoperasikan mesin jahit jarum 1/2, sabar dan teliti.', ARRAY['Fotokopi KTP & Ijazah', 'Pas Foto 3x4 (2 lembar)', 'Surat Keterangan Sehat'], 'Pabrik Mertoyudan, Magelang'),
  ('b0000001-0000-0000-0000-000000000016', 'a0000001-0000-0000-0000-000000000008', 'Staff Quality Control (QC Garmen & Finishing)', 'Penuh Waktu', 40, 'Rp 2.400.000 - Rp 3.200.000', 'Cermat dalam memeriksa cacat jahitan, kesesuaian ukuran pola (spec), dan kerapian pengemasan pakaian ekspor.', ARRAY['CV Lengkap', 'Fotokopi KTP & Ijazah', 'SKCK Aktif'], 'Pabrik Magelang'),
  ('b0000001-0000-0000-0000-000000000017', 'a0000001-0000-0000-0000-000000000008', 'Petugas Cutting & Packaging Ekspor', 'Penuh Waktu', 20, 'UMK Magelang + Insentif Shift', 'Fisik kuat, cekatan, teliti menghitung bundle kain dan melipat produk garmen sesuai instruksi kerja.', ARRAY['Surat Lamaran Kerja', 'Fotokopi KTP', 'Kartu Keluarga'], 'Pabrik Magelang'),
  ('b0000001-0000-0000-0000-000000000018', 'a0000001-0000-0000-0000-000000000009', 'Direct Sales Executive & Canvasser Outlet', 'Penuh Waktu', 35, 'UMK + Uang Bensin + Komisi Penjualan Menarik', 'Pria/Wanita memiliki sepeda motor & SIM C, komunikatif, menyukai tantangan target penjualan kartu perdana & paket data.', ARRAY['CV & Fotokopi SIM C', 'Fotokopi KTP & Ijazah', 'Pas Foto 4x6'], 'Area Magelang, Temanggung & Purworejo'),
  ('b0000001-0000-0000-0000-000000000019', 'a0000001-0000-0000-0000-000000000009', 'Promotor Digital & Event Representative', 'Penuh Waktu', 15, 'Rp 2.400.000 - Rp 3.400.000', 'Aktif di media sosial, percaya diri berbicara di depan umum, mampu menjelaskan promo paket seluler kepada pelanggan.', ARRAY['CV & Foto Diri Menarik', 'Fotokopi KTP', 'Ijazah Terakhir'], 'Booth Mall & Pusat Keramaian Magelang'),
  ('b0000001-0000-0000-0000-000000000020', 'a0000001-0000-0000-0000-000000000010', 'Account Officer (AO) Mekaar', 'Penuh Waktu', 80, 'UMK Wilayah + Fasilitas Motor Dinas + Tempat Tinggal / Mess', 'Khusus Perempuan, usia 18-22 tahun, belum menikah, mampu mengendarai sepeda motor (memiliki SIM C disukai), jujur.', ARRAY['Fotokopi KTP, KK & Ijazah/SKL', 'Surat Lamaran & CV', 'Surat Izin Orang Tua'], 'Cabang Unit Mekaar Magelang & Sekitarnya'),
  ('b0000001-0000-0000-0000-000000000021', 'a0000001-0000-0000-0000-000000000010', 'Finance Administration Officer (FAO) Mekaar', 'Penuh Waktu', 40, 'UMK Wilayah + Tunjangan Kinerja + Asuransi Kesehatan', 'Perempuan, teliti, menguasai pencatatan kas harian dan Microsoft Excel dengan baik.', ARRAY['CV Lengkap', 'Fotokopi Ijazah & Transkrip Rapor', 'Fotokopi KTP & KK'], 'Kantor Unit Mekaar Magelang'),
  ('b0000001-0000-0000-0000-000000000022', 'a0000001-0000-0000-0000-000000000011', 'Operator Pelintingan & Kemasan Produk', 'Penuh Waktu', 150, 'Sesuai UMK + Premi Hasil Kerja', 'Pria/Wanita usia 18-35 tahun, memiliki ketelitian dan ketangkasan tangan, tidak memiliki riwayat alergi aroma tembakau.', ARRAY['Fotokopi KTP & KK', 'Pas Foto 3x4 (2 lembar)', 'Surat Keterangan Sehat'], 'Pabrik Secang, Magelang'),
  ('b0000001-0000-0000-0000-000000000023', 'a0000001-0000-0000-0000-000000000011', 'Operator Mesin Sortir & Pengeringan Tembakau', 'Penuh Waktu', 35, 'Rp 2.400.000 - Rp 3.200.000', 'Pria usia maksimal 30 tahun, memahami dasar pengoperasian mesin konveyor dan motor listrik.', ARRAY['CV & Fotokopi Ijazah', 'KTP & SKCK Aktif', 'Surat Pengalaman Kerja (jika ada)'], 'Pabrik Secang'),
  ('b0000001-0000-0000-0000-000000000024', 'a0000001-0000-0000-0000-000000000011', 'Quality Control Tembakau', 'Penuh Waktu', 15, 'Rp 2.500.000 - Rp 3.400.000', 'Teliti menguji kadar air, tekstur rajangan daun tembakau, dan standar kemasan steril.', ARRAY['Daftar Riwayat Hidup', 'Transkrip Nilai / Rapor', 'Fotokopi KTP'], 'Pabrik Secang'),
